const lead = $('Split in Batches').item.json;
const scraperApiKey = $env.SCRAPER_API_KEY;

const scrape = async (targetUrl) => {
  if (!targetUrl || !targetUrl.trim()) return '';
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.scraperapi.com/?api_key=' + encodeURIComponent(scraperApiKey) + '&render=false&url=' + encodeURIComponent(targetUrl),
      timeout: 30000
    });
    return typeof res === 'string' ? res : (res.body || String(res) || '');
  } catch (_e) {
    return '';
  }
};

const [fbHtml, igHtml] = await Promise.all([
  lead.facebook_url  ? scrape(lead.facebook_url)  : Promise.resolve(''),
  lead.instagram_url ? scrape(lead.instagram_url) : Promise.resolve('')
]);

return [{
  json: {
    ...lead,
    fb_html: fbHtml,
    ig_html: igHtml
  }
}];

const lead = $json;
const cfg = $('config').first().json;
const apiKey = $env.OPENAI_API_KEY;
const agencyName = cfg.agencyName || 'Atrium Solution';
const calendarLink = cfg.calendarLink || 'https://calendly.com/atrium-solution';
const model = cfg.openaiModel || 'gpt-4o-mini';

function safeParsePS(resp) {
  if (!resp || resp.error || !resp.lighthouseResult) return null;
  const lr = resp.lighthouseResult;
  return {
    performance: lr.categories?.performance?.score != null
      ? Math.round(lr.categories.performance.score * 100) : null,
    seo: lr.categories?.seo?.score != null
      ? Math.round(lr.categories.seo.score * 100) : null,
    audits: lr.audits || {}
  };
}

const mobile = safeParsePS($('HTTP — PageSpeed Mobile').item.json);
const desktop = safeParsePS($('HTTP — PageSpeed Desktop').item.json);

const websitePP = [];
const mobileScore = mobile?.performance ?? null;

if (mobileScore !== null) {
  if (mobileScore < 50) {
    websitePP.push({ area: 'performance', problem: `Mobile speed score is ${mobileScore}/100 — site loads very slowly on phones, causing visitors to leave`, solution: 'Mobile speed optimization, image compression, lazy loading, and caching setup', severity: 'high' });
  } else if (mobileScore < 80) {
    websitePP.push({ area: 'performance', problem: `Mobile speed score is ${mobileScore}/100 — noticeable delays for mobile users`, solution: 'Core Web Vitals improvements and performance optimization', severity: 'medium' });
  }
} else {
  websitePP.push({ area: 'performance', problem: 'Website performance could not be measured — possible technical issues or very slow response', solution: 'Website technical audit, hosting review, and performance baseline setup', severity: 'medium' });
}

const desktopScore = desktop?.performance ?? null;
if (desktopScore !== null && desktopScore < 70) {
  websitePP.push({ area: 'performance', problem: `Desktop speed score is ${desktopScore}/100 — below the 70+ industry standard`, solution: 'Desktop performance optimization and server-side improvements', severity: 'medium' });
}

const seoScore = mobile?.seo ?? null;
if (seoScore !== null && seoScore < 80) {
  websitePP.push({ area: 'seo', problem: `SEO score is ${seoScore}/100 — website is harder to find on Google`, solution: 'On-page SEO optimization, meta tags, and content structure improvements', severity: seoScore < 60 ? 'high' : 'medium' });
}

const audits = mobile?.audits || {};
if (audits['meta-description']?.score === 0) websitePP.push({ area: 'seo', problem: 'Missing meta description — Google shows no meaningful summary in search results', solution: 'Write compelling meta descriptions for all key pages', severity: 'medium' });
if (audits['document-title']?.score === 0) websitePP.push({ area: 'seo', problem: 'Missing or generic page title — reduces click-through rate from Google', solution: 'Optimize page titles with relevant keywords and business name', severity: 'medium' });
if (audits['tap-targets']?.score === 0) websitePP.push({ area: 'ux', problem: 'Buttons and links too small on mobile — frustrating for customers on phones', solution: 'Mobile UX redesign with properly sized tap targets and spacing', severity: 'medium' });
if (audits['uses-https']?.score === 0) websitePP.push({ area: 'security', problem: 'Website not using HTTPS — browsers show a Not Secure warning to every visitor', solution: 'Install SSL certificate and enforce HTTPS across entire site', severity: 'high' });
if (audits['image-alt']?.score === 0) websitePP.push({ area: 'seo', problem: 'Images missing alt text — hurts both SEO rankings and accessibility compliance', solution: 'Add descriptive alt text to all website images', severity: 'low' });

const socialPP = [];
const fbHtml = (lead.fb_html || '').toLowerCase();
const igHtml = (lead.ig_html || '').toLowerCase();
const hasFB = !!(lead.facebook_url && lead.facebook_url.trim());
const hasIG = !!(lead.instagram_url && lead.instagram_url.trim());

if (hasFB) {
  if (!fbHtml || fbHtml.length < 300 || fbHtml.includes('you must log in') || fbHtml.includes('log into facebook')) {
    socialPP.push({ platform: 'facebook', problem: 'Facebook page is private or inaccessible to the public — potential customers cannot find it', solution: 'Set up a public Facebook Business page with full info and regular updates', severity: 'medium' });
  } else {
    const recentKW = ['just now', 'minutes ago', 'hour', 'yesterday', 'days ago'];
    if (!recentKW.some(k => fbHtml.includes(k))) {
      socialPP.push({ platform: 'facebook', problem: 'Facebook page appears inactive — no recent posts detected, reducing trust and reach', solution: 'Consistent posting strategy and social media content calendar', severity: 'medium' });
    }
  }
} else {
  socialPP.push({ platform: 'facebook', problem: 'No Facebook Business page linked on the website — missing a key customer engagement channel', solution: 'Create and promote a Facebook Business page with regular updates and customer reviews', severity: 'medium' });
}

if (hasIG) {
  if (!igHtml || igHtml.length < 300 || igHtml.includes('log in') || igHtml.includes('this page isn')) {
    socialPP.push({ platform: 'instagram', problem: 'Instagram profile is private or inaccessible to the public', solution: 'Set up a public Instagram Business profile with consistent branding and content', severity: 'medium' });
  } else if (!igHtml.includes('posts') && !igHtml.includes('followers')) {
    socialPP.push({ platform: 'instagram', problem: 'Instagram profile appears thin or inactive — limited social proof for potential customers', solution: 'Build Instagram presence with regular posts and engagement strategy', severity: 'medium' });
  }
} else {
  socialPP.push({ platform: 'instagram', problem: 'No Instagram profile linked on website — missing visual marketing and younger audience reach', solution: 'Create Instagram Business account showcasing work, reviews, and behind-the-scenes content', severity: 'low' });
}

const allPP = [...websitePP, ...socialPP];
const ppText = allPP.map((p, i) =>
  `${i + 1}. [${(p.area || p.platform).toUpperCase()} | ${p.severity.toUpperCase()}] ${p.problem}\n   Fix: ${p.solution}`
).join('\n');

const systemPrompt = `You are a senior digital marketing consultant writing personalized cold outreach emails for ${agencyName}. Your job is to show the business owner you did real homework on their website and social media — then offer specific solutions.\n\nStrict rules:\n- Tone: professional, empathetic, consultative — NOT salesy or pushy\n- Reference SPECIFIC numbers and issues from the audit data\n- Structure: brief intro (1 sentence) → 2-3 specific problems found → how we help → soft CTA\n- Subject line: under 60 characters, no spam words, creates curiosity\n- Body: under 250 words total\n- Close with: Book a free 15-minute strategy call: ${calendarLink}\n- Sign off: The ${agencyName} Team\n\nOutput format — use EXACTLY this structure with nothing before or after:\nSUBJECT: <subject line here>\nBODY:\n<full email body here>`;

const userPrompt = `Write a cold outreach email for this business:\n\nBusiness Name: ${lead.business_name}\nIndustry: ${lead.category}\nLocation: ${lead.city}${lead.state ? ', ' + lead.state : ''}\nWebsite: ${lead.website_url}\nGoogle Rating: ${lead.rating ? lead.rating + '/5 (' + lead.review_count + ' reviews)' : 'Not available'}\n\nAudit Findings:\n${ppText}\n\nWrite the personalized outreach email now.`;

let auditSuccess = false;
let emailSubject = null;
let emailBody = null;
let failureReason = null;

if (!apiKey) {
  failureReason = 'missing OPENAI_API_KEY env var';
} else {
  const http = this.helpers.httpRequest;
  let lastErr = 'unknown OpenAI error';
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const res = await http({
        method: 'POST',
        url: 'https://api.openai.com/v1/chat/completions',
        headers: {
          Authorization: 'Bearer ' + apiKey,
          'Content-Type': 'application/json'
        },
        body: {
          model,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ],
          max_tokens: 700,
          temperature: 0.7
        },
        json: true,
        timeout: 60000
      });

      const content = (res?.choices?.[0]?.message?.content || '').trim();
      if (content.length >= 50) {
        const subjectMatch = content.match(/^SUBJECT:\s*(.+?)$/m);
        const bodyMatch = content.match(/^BODY:\s*([\s\S]+)$/m);
        emailSubject = subjectMatch
          ? subjectMatch[1].trim()
          : 'Improve ' + lead.business_name + "'s Online Presence";
        emailBody = bodyMatch
          ? bodyMatch[1].trim()
          : content.replace(/^SUBJECT:.+$/m, '').trim();
        if (emailBody && emailBody.length >= 50) {
          auditSuccess = true;
          break;
        }
        lastErr = 'could not parse email body from AI response';
      } else {
        lastErr = res?.error?.message || 'AI returned empty response';
      }
    } catch (e) {
      lastErr = e.message || 'OpenAI HTTP request failed';
      if (attempt < 2) await new Promise(r => setTimeout(r, 3000));
    }
  }
  if (!auditSuccess) failureReason = lastErr;
}

return [{
  json: {
    id: lead.id,
    business_name: lead.business_name,
    email: lead.email,
    website_url: lead.website_url,
    city: lead.city,
    state: lead.state,
    category: lead.category,
    rating: lead.rating,
    review_count: lead.review_count,
    campaign_id: lead.campaign_id,
    pagespeed_mobile: mobileScore,
    pagespeed_desktop: desktopScore,
    seo_score: seoScore,
    website_pain_points: websitePP,
    social_pain_points: socialPP,
    pain_points_count: allPP.length,
    audit_success: auditSuccess,
    email_subject: emailSubject,
    email_body: emailBody,
    failure_reason: failureReason
  }
}];

const cfg = $('config').first().json;
const start = new Date(cfg.runStartTs).getTime();
const durationMs = Number.isFinite(start) ? Date.now() - start : 0;

return [{
  json: {
    workflow_name: 'audit_and_draft',
    run_start_ts: cfg.runStartTs,
    duration_ms: durationMs,
    notes: 'WF3 audit_and_draft batch completed at ' + new Date().toISOString()
  }
}];
